import os, json, csv, numpy as np, time

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
P_CONS_MAIN = 'storage/noesis/nmap/consensus_n26_tol1e8.json'
P_CONS_ALT  = 'storage/noesis/nmap/consensus_n26_noesis243_scientia259_prometheus298_v6_tol1e8.json'
P_BOUND_SOTA = 'storage/noesis/exports/sota_243/active_boundary_tol1e8.csv'

OUT_BOUND = 'storage/noesis/nmap/n26_consensus_boundary_eq.csv'
OUT_PAIRS = 'storage/noesis/nmap/n26_consensus_pairs_eq.csv'
OUT_RESID = 'storage/noesis/nmap/n26_consensus_residuals_for_sota243.json'

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def try_load_consensus():
    if os.path.exists(P_CONS_MAIN):
        return load_json(P_CONS_MAIN)
    if os.path.exists(P_CONS_ALT):
        return load_json(P_CONS_ALT)
    return None

def fallback_boundary_from_sota():
    rows = []
    if not os.path.exists(P_BOUND_SOTA):
        return rows
    with open(P_BOUND_SOTA, 'r') as f:
        r = csv.reader(f); next(r, None)
        for row in r:
            try:
                i = int(row[0]); kind = row[1].strip()
                rows.append((i, kind))
            except Exception:
                continue
    return rows

def normalize_consensus(cons):
    bcore = cons.get('boundary_core', [])
    pcore = cons.get('pairs_core', [])
    # Accept multiple possible shapes: list of [i, wall] and [i,j]
    b_rows = []
    for it in bcore:
        try:
            i = int(it[0]); w = str(it[1])
            b_rows.append((i, w))
        except Exception:
            continue
    p_rows = []
    for it in pcore:
        try:
            i = int(it[0]); j = int(it[1])
            if i == j: continue
            i0, j0 = (i, j) if i < j else (j, i)
            p_rows.append((i0, j0))
        except Exception:
            continue
    # Deduplicate
    p_rows = sorted(list(set(p_rows)))
    return b_rows, p_rows

def write_csv(path, rows, header=None):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', newline='') as f:
        w = csv.writer(f)
        if header: w.writerow(header)
        for r in rows: w.writerow(r)

def residuals_vs_sota(b_rows, p_rows):
    c = np.loadtxt(P_C, dtype=float).reshape(N, 2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    # Boundary residuals
    b_res = []
    for (i, w) in b_rows:
        if w in ('xmin', 'xL', 'x_min'):
            val = c[i,0] - r[i]
        elif w in ('xmax', 'xR', 'x_max'):
            val = 1.0 - c[i,0] - r[i]
        elif w in ('ymin', 'yB', 'y_min'):
            val = c[i,1] - r[i]
        elif w in ('ymax', 'yT', 'y_max'):
            val = 1.0 - c[i,1] - r[i]
        else:
            val = np.nan
        b_res.append(float(val))
    # Pair residuals
    p_res = []
    for (i, j) in p_rows:
        d = float(np.hypot(c[i,0] - c[j,0], c[i,1] - c[j,1]))
        p_res.append(float(d - (r[i] + r[j])))
    out = {
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'n_boundary_eq': len(b_rows),
        'n_pairs_eq': len(p_rows),
        'boundary_residual_min': (None if not b_res else float(np.min(b_res))),
        'boundary_residual_max': (None if not b_res else float(np.max(b_res))),
        'pairs_residual_min': (None if not p_res else float(np.min(p_res))),
        'pairs_residual_max': (None if not p_res else float(np.max(p_res)))
    }
    os.makedirs(os.path.dirname(OUT_RESID), exist_ok=True)
    with open(OUT_RESID, 'w') as f:
        json.dump(out, f, indent=2)

def construct_packing():
    # Load consensus if present
    b_rows, p_rows = [], []
    cons = try_load_consensus()
    if cons is not None and ('boundary_core' in cons or 'pairs_core' in cons):
        b_rows, p_rows = normalize_consensus(cons)
    # Fallback for boundary: use SOTA boundary set as consensus proxy
    if not b_rows:
        b_rows = fallback_boundary_from_sota()
    # Write CSVs
    write_csv(OUT_BOUND, [(i, w) for (i, w) in b_rows], header=['i','wall'])
    write_csv(OUT_PAIRS, [(i, j) for (i, j) in p_rows], header=['i','j'])
    # Residuals vs SOTA_243
    residuals_vs_sota(b_rows, p_rows)

    # Return SOTA snapshot with a tiny shrink
    c = np.loadtxt(P_C, dtype=float).reshape(N, 2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    r = np.maximum(r - SAFETY, R_MIN)
    return c.astype(float), r.astype(float)
